import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"D5.1 · Memory Core 与记忆浏览器","description":"Hearth D5.1 开发增量：用户能看到 Hearth 记住了什么、来自哪里、为什么被召回，并能纠正或删除。","frontmatter":{"title":"D5.1 · Memory Core 与记忆浏览器","description":"Hearth D5.1 开发增量：用户能看到 Hearth 记住了什么、来自哪里、为什么被召回，并能纠正或删除。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-5/d5-1.md","filePath":"delivery/stage-5/d5-1.md","lastUpdated":null}'),r={name:"delivery/stage-5/d5-1.md"};function o(s,a,d,h,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 5 · D5.1 · 1 / 4</p><h1 id="d5-1-·-memory-core-与记忆浏览器" tabindex="-1">D5.1 · Memory Core 与记忆浏览器 <a class="header-anchor" href="#d5-1-·-memory-core-与记忆浏览器" aria-label="Permalink to &quot;D5.1 · Memory Core 与记忆浏览器&quot;">​</a></h1><p class="lead">先让记忆可解释、可纠正，再让系统依靠它工作；用户必须知道记住了什么、来自哪里以及为什么被召回。</p><p class="page-meta">STAGE 5 · D5.1 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>用户能看到 Hearth 记住了什么、来自哪里、为什么被召回，并能纠正或删除。</div><div><strong>完成门槛</strong>记忆有来源和敏感度；召回可解释；错误记忆可纠正；敏感信息不进入不应出现的上下文；记忆预算生效。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>用户能看到 Hearth 记住了什么、来自哪里、为什么被召回，并能纠正或删除。</p><p>Stage 5 先让记忆可纠正、可遗忘，再让技能可评估、可回滚；任何不能解释来源和权限的变化都不能进入生产。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>Stage 1–4 的任务、审批、验证、主动性和跨设备入口已经稳定。</li><li>已确定允许记忆的事实、偏好、经验和敏感信息边界。</li><li>每次技能变化都必须有对照评估、版本、权限交集和回滚路径。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-记忆类型与最小模型" tabindex="-1">01 · 记忆类型与最小模型 <a class="header-anchor" href="#_01-·-记忆类型与最小模型" aria-label="Permalink to &quot;01 · 记忆类型与最小模型&quot;">​</a></h3><p>定义 Episodic、Semantic、Procedural、Preference 和 Relationship 五类，但先只实现任务所需的 Episodic 与 Semantic 路径。每条记录包含来源、置信度、敏感度、观察时间、更新时间、作用域和过期策略，不允许无来源的模型总结进入长期记忆。</p><h3 id="_02-·-写入、检索与上下文注入" tabindex="-1">02 · 写入、检索与上下文注入 <a class="header-anchor" href="#_02-·-写入、检索与上下文注入" aria-label="Permalink to &quot;02 · 写入、检索与上下文注入&quot;">​</a></h3><p>写入区分用户明确确认、任务产物观察和模型推断，推断默认低置信度且不能改变权限。检索按任务目标、项目、时间和敏感度过滤，Context Pack 记录入选原因与预算；召回失败或置信度不足时明确说不知道。</p><h3 id="_03-·-为什么召回与记忆浏览" tabindex="-1">03 · 为什么召回与记忆浏览 <a class="header-anchor" href="#_03-·-为什么召回与记忆浏览" aria-label="Permalink to &quot;03 · 为什么召回与记忆浏览&quot;">​</a></h3><p>记忆浏览器按类型、项目、时间和敏感度展示记录，详情页说明何时、从哪条证据写入，为什么在本次任务被召回。用户能纠正值、标记敏感、删除记录或缩小作用域；纠正产生新版本，不覆盖被撤销的历史证据。</p><h3 id="_04-·-敏感隔离与跨项目边界" tabindex="-1">04 · 敏感隔离与跨项目边界 <a class="header-anchor" href="#_04-·-敏感隔离与跨项目边界" aria-label="Permalink to &quot;04 · 敏感隔离与跨项目边界&quot;">​</a></h3><p>敏感记忆使用单独作用域和加密字段，不进入普通任务摘要、推送或诊断导出。跨账户、跨项目建立硬隔离，测试要证明错误记忆可纠正、敏感内容不进入不应出现的上下文、删除后不再被召回。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>packages/memory/core</code> — 五类记忆模型、写入、检索与冲突</li><li><code>packages/memory/provenance</code> — 来源、置信度、敏感度、时效与召回解释</li><li><code>packages/memory/forget</code> — 索引、缓存、设备传播与遗忘审计</li><li><code>packages/memory/browser</code> — 记忆浏览、纠正、删除与导出页面</li><li><code>packages/evolution/trajectory</code> — 轨迹采集、重放、脱敏与样本分层</li><li><code>packages/evolution/skills</code> — manifest、权限、版本、签名与运行时选择</li><li><code>packages/evolution/evaluation</code> — 评估集、baseline、Shadow、Canary 与回滚</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>MemoryRecord</code></td><td>memoryId、kind、value、provenance、confidence、sensitivity、observedAt、updatedAt、expiresAt；冲突不得静默覆盖。</td></tr><tr><td><code>ForgetRequest</code></td><td>targetIds、scope、reason、requestedAt、propagationState、auditId；删除必须传播到索引、缓存和设备。</td></tr><tr><td><code>SkillManifest</code></td><td>skillId、version、inputs、outputs、requiredCapabilities、evaluationRef、signature、status；权限只能取交集。</td></tr><tr><td><code>EvolutionDecision</code></td><td>candidateId、stage、baseline、shadowResult、canaryResult、permissionDelta、rollbackRef；每次晋升可追溯。</td></tr><tr><td><code>TrajectoryRecord</code></td><td>taskId、steps、toolCalls、inputsDigest、results、failureClass、consent、redactions；重放不得产生外部副作用。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:memory：写入、召回、冲突、纠正、遗忘和跨项目隔离</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:poison：提示注入、来源伪造、权限提升和记忆污染</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:evolution：权限交集、Shadow、Canary、晋升和回滚</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:skills：候选与</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 的同任务对照和污染防护</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-5/d5-1.html">D5.1 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：记忆类型与最小模型、写入、检索与上下文注入、为什么召回与记忆浏览、敏感隔离与跨项目边界。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“错误记忆被召回”。页面必须显示“召回卡显示来源与原因，用户可以纠正或删除。”，然后按“更新记忆、重建索引并记录纠正事件。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：记忆有来源和敏感度；召回可解释；错误记忆可纠正；敏感信息不进入不应出现的上下文；记忆预算生效。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>Memory Core</li><li>记忆浏览器与召回解释</li><li>纠正/删除演示</li><li>敏感上下文测试</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 记忆有来源和敏感度；召回可解释；错误记忆可纠正；敏感信息不进入不应出现的上下文；记忆预算生效。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>错误记忆被召回</td><td>召回卡显示来源与原因，用户可以纠正或删除。</td><td>更新记忆、重建索引并记录纠正事件。</td></tr><tr><td>遗忘没有传播</td><td>页面显示“遗忘未完成”并阻止继续依赖。</td><td>重试索引清理、设备同步和缓存失效，确认后再标记完成。</td></tr><tr><td>候选技能权限扩大</td><td>评估标记权限越界并直接拒绝晋升。</td><td>收窄 manifest 权限或重新设计技能，保持权限交集。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不允许无来源、无评估、无回滚的技能自动上线。</li><li>不允许记忆投毒改变权限、审批策略或系统事实。</li><li>不用“模型觉得有用”替代可重复评估。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/architecture/memory.html">记忆系统</a></li><li><a href="/hearth-os/architecture/evolution.html">技能进化</a></li><li><a href="/hearth-os/architecture/evaluation.html">评估体系</a></li><li><a href="/hearth-os/architecture/security-privacy.html">安全与隐私</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>继续 <a href="/hearth-os/delivery/stage-5/d5-2.html">D5.2 · 记忆冲突、遗忘与导出</a>。先完成本增量验收，不要用后续工作掩盖当前缺口。</p>`,42)])])}const k=e(r,[["render",o]]);export{u as __pageData,k as default};
